import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import http from 'node:http';import https from 'node:https';import net from 'node:net';import {once} from 'node:events';
import {createProxyManager}from'../../src/services/proxyManager.js';import{createProxyManagerApp}from'../../src/routes/proxyManagerApp.js';import{createProxyManagerClient}from'../../src/services/proxyManagerClient.js';import{createHttpExecutor,createProxiedSession}from'../../src/services/socialHttpTransport.js';import{runCrawlerQueue}from'../../src/services/crawlerQueueContext.js';import{boundedProxyRead}from'../../src/services/crawlerQueueFlow.js';
const dir=process.argv[2],connections=new Set();let connects=0,lastSocket,race=false,dropConnect=false;const reuse=[];
const origin=https.createServer({key:fs.readFileSync(path.join(dir,'key.pem')),cert:fs.readFileSync(path.join(dir,'cert.pem'))},(req,res)=>{if(req.url==='/redirect'){res.writeHead(302,{location:'/robots.txt','content-length':'2'});res.end('go');return;}res.setHeader('content-length','2');res.end('ok');});origin.keepAliveTimeout=60000;
const proxy=http.createServer();proxy.on('connect',(_req,client,head)=>{connects++;connections.add(client);client.on('close',()=>connections.delete(client));if(dropConnect){client.end();return;}const upstream=net.connect(origin.address().port,'127.0.0.1',()=>{client.write('HTTP/1.1 200 Connection Established\r\n\r\n');if(head.length)upstream.write(head);client.pipe(upstream);upstream.pipe(client);});connections.add(upstream);upstream.on('close',()=>connections.delete(upstream));client.on('error',()=>upstream.destroy());upstream.on('error',()=>client.destroy());});
const listen=async server=>{server.listen(0,'127.0.0.1');await once(server,'listening');};await listen(origin);await listen(proxy);
const keysFile=path.join(dir,'keys.json'),settingsFile=path.join(dir,'settings.json');fs.writeFileSync(keysFile,JSON.stringify(['warm-transport-test-key']));fs.writeFileSync(settingsFile,JSON.stringify({unrestrictedSharing:true,backgroundActiveKeyCount:1,backgroundQueueColdProbe:{'crawler-flow-facebook-group-source':true}}));let clock=Date.now();
const manager=createProxyManager({keysFile,settingsFile,now:()=>clock,leaseIdleMs:900000,makeRotator:()=>async()=>({host:'127.0.0.1',port:proxy.address().port,expiresAt:Date.now()+900000})});
await manager.tick();const key='test-warm-transport-auth-00000000000000000',backgroundKey='test-background-warm-auth-000000000000000',app=createProxyManagerApp({manager,key,backgroundKey});const rpc=http.createServer(app);await listen(rpc);const provider=createProxyManagerClient({url:'http://127.0.0.1:'+rpc.address().port,key:backgroundKey});
const execute=createHttpExecutor({getProxy:provider,respectPlatformCooldown:false,failFastProxy:true,timeoutMs:3000,attemptTimeoutMs:10000,makeSession:options=>createProxiedSession({...options,proxy:{...options.proxy,beforeRequest:async control=>{reuse.push(control.reuseTransport);if(race&&control.reuseTransport)lastSocket.destroy();return options.proxy.beforeRequest(control);}},requestImpl:(url,opts,callback)=>{const req=https.request(url,opts,callback);req.on('socket',socket=>lastSocket=socket);return req;}})}),binding={},target={platform:'facebook',operation:'source',sourceType:'group',proxyRetryContext:{}};
const work=async session=>{const r=await session.request('https://www.facebook.com/robots.txt');return{status:'ok',http:r.httpStatus};};let peer;
try{
 await runCrawlerQueue('crawler-flow-facebook-group-source',async()=>{
  const first=await execute(target,work,binding);assert.equal(first.status,'ok');assert.equal(lastSocket.authorized,true);assert.equal(connects,1);
  peer=await provider(target);await peer.report({status:'proxy_error',reason:'PROXY_TLS_HANDSHAKE_TIMEOUT',phase:'proxy_tls',connectStatus:200});
  const second=await execute(target,work,binding);assert.equal(second.status,'ok',JSON.stringify(second));assert.equal(connects,1);assert.deepEqual(reuse,[false,true]);assert.equal(manager.status().totals.warmTransportPermits,1);const redirect=await execute(target,async session=>({status:'ok',http:(await session.request('https://www.facebook.com/redirect')).httpStatus}),binding);assert.equal(redirect.http,200,JSON.stringify(redirect));assert.equal(connects,1);
  // Kill the very socket that justified a warm permit before the RPC returns.
  // Conditional permission must not silently become a new CONNECT.
  race=true;const failed=await execute(target,work,binding);assert.equal(failed.reason,'PROXY_ENDPOINTS_UNAVAILABLE',JSON.stringify(failed));assert.equal(connects,1);assert.equal(reuse.at(-1),true);
  let spent=0;const result=await boundedProxyRead({proxyAttemptLimit:10,initialProxyEndpoints:Array.from({length:9},(_,i)=>(i+1).toString(16).padStart(64,'0')),read:async()=>({good:false,result:failed}),rotate:async()=>{},onProxyAttempt:async()=>spent++});assert.equal(result.deferred,true);assert.equal(spent,0);
 });
 race=false;await runCrawlerQueue('crawler-flow-facebook-page-source',async()=>{const pageBinding={},r=await execute({...target,sourceType:'page'},work,pageBinding);assert.equal(r.status,'ok',JSON.stringify(r));assert.equal(connects,2);await pageBinding.dispose();});
 // After quarantine, only one actual group CONNECT is admitted until its
 // result proves recovery. The other group request waits without using TCP.
 clock+=120001;let ready,finishRecovery;const started=new Promise(resolve=>ready=resolve),hold=new Promise(resolve=>finishRecovery=resolve),recoveringBinding={};
 const recovering=runCrawlerQueue('crawler-flow-facebook-group-source',()=>execute(target,async session=>{const r=await work(session);ready();await hold;return r;},recoveringBinding));
 await started;const before=connects;const waitingBinding={};const waiting=await runCrawlerQueue('crawler-flow-facebook-group-source',()=>execute(target,work,waitingBinding));assert.equal(waiting.reason,'PROXY_ENDPOINTS_UNAVAILABLE',JSON.stringify(waiting));assert.equal(waiting.transport.proxyUsed,false);assert.equal(connects,before);
 const otherPage={};const pageDuringRecovery=await runCrawlerQueue('crawler-flow-facebook-page-source',()=>execute({...target,sourceType:'page'},work,otherPage));assert.equal(pageDuringRecovery.status,'ok',JSON.stringify(pageDuringRecovery));assert.equal(connects,before+1);await otherPage.dispose();
 finishRecovery();assert.equal((await recovering).status,'ok');assert.equal(manager.status().coldRecoveryProbes.length,0);const nextGroup={};const recovered=await runCrawlerQueue('crawler-flow-facebook-group-source',()=>execute(target,work,nextGroup));assert.equal(recovered.status,'ok',JSON.stringify(recovered));assert.equal(connects,before+2);await nextGroup.dispose();await recoveringBinding.dispose();await waitingBinding.dispose?.();
 dropConnect=true;await runCrawlerQueue('crawler-flow-facebook-user-source',async()=>{const b={},r=await execute({...target,sourceType:'user'},work,b);assert.equal(r.reason,'PROXY_CONNECT_EOF',JSON.stringify(r));assert.ok(manager.status().endpointAvoidance.some(x=>x.scope==='crawler-flow-facebook-user-source'&&x.phase==='proxy_connect'));await b.dispose?.();});
 let attempts=0;const eof=await boundedProxyRead({proxyAttemptLimit:10,read:async()=>({good:false,result:{status:'proxy_error',reason:'PROXY_CONNECT_EOF',transport:{proxyUsed:true,proxyEndpoint:(++attempts).toString(16).padStart(64,'0')}}}),rotate:async()=>{}});assert.equal(eof.failed,true);assert.equal(attempts,10);
 console.log(JSON.stringify({coldConnects:connects,singleRecoveryConnect:true,warmRequestSucceeded:true,closedWarmSocketDidNotReconnect:true,queueIsolation:true,proxyBudgetSpentOnWait:0}));
}finally{await binding.dispose?.();await peer?.release();manager.close();for(const socket of connections)socket.destroy();for(const server of [origin,proxy,rpc]){server.closeAllConnections?.();await new Promise(resolve=>server.close(resolve));}}
